package mapper;import entity.LoaiSanPham;import java.sql.ResultSet;import java.sql.SQLException;public class LoaiSanPhamMapper implements RowMapper<LoaiSanPham> {    @Override    public LoaiSanPham mapper(ResultSet rs) {        try {            String maLoai = rs.getString("maLoai");            String tenLoaiSanPham = rs.getString("tenLoaiSanPham");            return new LoaiSanPham(maLoai, tenLoaiSanPham);        } catch (SQLException e) {            return null;        }    }}